

-- -----------------------------
-- Work location table (create-if-missing)
-- -----------------------------
-- Portable create table: H2 / modern DBs compatible. Adjust if your DB
-- requires different auto-increment syntax (MySQL uses AUTO_INCREMENT, Postgres uses SERIAL).
CREATE TABLE IF NOT EXISTS work_location (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  description VARCHAR(1024),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);




CREATE TABLE IF NOT EXISTS post (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  description VARCHAR(1024),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

